flow.set('sim', {
  t: 0, seed: 42, scenario: 'normal',
  level: 60, pressure: 4.2, qOut: 40,
  p01: 'Running', p02: 'Stopped',
  blockage: 0, inflowFactor: 1, faultTimer: 0, interlock: false,
  alarms: { LOW_LEVEL: false, LOW_LOW_LEVEL: false, HIGH_PRESSURE: false, PUMP_FAULT: false }
});
node.status({ fill: 'green', shape: 'dot', text: 'state initialised' });
return null;

// ===== Parameters (later: move to config/thresholds.json) =====
const C = {
  dt: 2,                       // s per tick
  tank: 20, qRated: 40, pRated: 4.2, pIdle: 0.2,
  autoStart: 6,                // s before standby starts
  inNom: 40, inAmp: 15, wave: 900,
  ts: { normal: 1, low_level: 5, high_pressure: 1, pump_fault: 1 }  // time-scale for level only
};

const s = flow.get('sim');
if (!s) { node.warn('State not initialised'); return null; }

// ===== Helpers: seeded RNG (mulberry32) + gaussian =====
function rnd() {
  s.seed = (s.seed + 0x6D2B79F5) | 0;
  let t = s.seed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function gauss(sd) {
  const u = 1 - rnd(), v = rnd();
  return sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const round = (x, d) => Math.round(x * 10 ** d) / 10 ** d;

s.t += C.dt;
const A = s.alarms;
const prev = Object.assign({}, A);

// 1. Scenario dynamics
if (s.scenario === 'high_pressure') s.blockage = Math.min(0.5, s.blockage + 0.02);

// 2. Tank level (uses previous tick's outflow)
const qin = C.inNom * s.inflowFactor +
  (s.inflowFactor > 0 ? C.inAmp * Math.sin(2 * Math.PI * s.t / C.wave) : 0);
const ts = C.ts[s.scenario] || 1;
s.level = clamp(s.level + (qin - s.qOut) / (C.tank * 0.01) * (C.dt / 3600) * ts, 0, 100);
const lt = clamp(round(s.level + gauss(0.15), 1), 0, 100);

// 3. Level alarms (with hysteresis) + interlock (latched until reset)
if (!A.LOW_LEVEL && lt < 20) A.LOW_LEVEL = true;
else if (A.LOW_LEVEL && lt > 25) A.LOW_LEVEL = false;
if (!A.LOW_LOW_LEVEL && lt < 10) A.LOW_LOW_LEVEL = true;
else if (A.LOW_LOW_LEVEL && lt > 30) A.LOW_LOW_LEVEL = false;
if (A.LOW_LOW_LEVEL) s.interlock = true;
if (s.interlock) {
  if (s.p01 === 'Running') s.p01 = 'Stopped';
  if (s.p02 === 'Running') s.p02 = 'Stopped';
}

// 4. Standby auto-start after main pump fault
if (s.p01 === 'Fault' && s.p02 === 'Stopped' && !s.interlock) {
  s.faultTimer += C.dt;
  if (s.faultTimer >= C.autoStart) s.p02 = 'Running';
}

// 5. Outlet flow & pressure (common header)
const n = (s.p01 === 'Running') + (s.p02 === 'Running');
s.qOut = n * C.qRated * (1 - 0.15 * s.blockage);
const pTarget = n > 0 ? C.pRated * (1 + s.blockage) : C.pIdle;
s.pressure += (pTarget - s.pressure) * 0.5;
const ft = n > 0 ? Math.max(0.1, round(s.qOut + gauss(0.4), 1)) : 0;
const pt = Math.max(0, round(s.pressure + gauss(0.03), 2));

// 6. Pressure / pump alarms
if (!A.HIGH_PRESSURE && pt > 6.0) A.HIGH_PRESSURE = true;
else if (A.HIGH_PRESSURE && pt < 5.5) A.HIGH_PRESSURE = false;
A.PUMP_FAULT = (s.p01 === 'Fault' || s.p02 === 'Fault');

// 7. Build messages
const now = new Date().toISOString();
const info = {
  LOW_LEVEL:     { sev: 'warning',  tag: 'LT01', val: lt, thr: 20 },
  LOW_LOW_LEVEL: { sev: 'critical', tag: 'LT01', val: lt, thr: 10 },
  HIGH_PRESSURE: { sev: 'warning',  tag: 'PT01', val: pt, thr: 6.0 },
  PUMP_FAULT:    { sev: 'critical' }
};
const events = [];
for (const code of Object.keys(A)) {
  if (A[code] !== prev[code]) {
    const i = info[code];
    const ev = { ts: now, station: 'PS01', code, severity: i.sev, active: A[code] };
    if (i.tag) { ev.tag = i.tag; ev.value = i.val; ev.threshold = i.thr; }
    events.push({ topic: 'plant/ps01/events', payload: ev });
  }
}

const tele = {
  topic: 'plant/ps01/telemetry',
  payload: {
    ts: now, station: 'PS01', scenario: s.scenario,
    tags: {
      LT01: { asset: 'T01',   value: lt, unit: '%',    quality: 'good' },
      PT01: { asset: 'OUT01', value: pt, unit: 'bar',  quality: 'good' },
      FT01: { asset: 'OUT01', value: ft, unit: 'm3/h', quality: 'good' }
    },
    pumps: {
      P01: { status: s.p01, role: 'main' },
      P02: { status: s.p02, role: 'standby' }
    },
    alarms: Object.keys(A).filter(k => A[k])
  }
};

flow.set('sim', s);
node.status({ text: `${s.scenario} | L=${lt} P=${pt} F=${ft}` });
return [tele, events];

const cmd = msg.payload && msg.payload.scenario;
const valid = ['normal', 'reset', 'low_level', 'high_pressure', 'pump_fault'];
const s = flow.get('sim');
if (!s) { node.warn('State not initialised'); return null; }
if (!valid.includes(cmd)) {
  node.warn('Unknown scenario: ' + JSON.stringify(msg.payload));
  return null;
}

// Every command starts from a clean baseline, then applies the scenario.
// Alarm flags are NOT cleared here: the tick clears them via hysteresis,
// so the matching "active:false" events are still published.
s.level = 60;
s.p01 = 'Running';
s.p02 = 'Stopped';
s.blockage = 0;
s.inflowFactor = 1;
s.faultTimer = 0;
s.interlock = false;
s.scenario = (cmd === 'reset') ? 'normal' : cmd;

if (cmd === 'low_level') s.inflowFactor = 0;   // cut inflow -> level drains
if (cmd === 'pump_fault') s.p01 = 'Fault';     // blockage for high_pressure ramps in tick

flow.set('sim', s);
node.status({ fill: 'blue', shape: 'dot', text: 'scenario: ' + s.scenario });
msg.payload = { applied: s.scenario };
return msg;
